  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1

* Load capacitor
CL Out 0 1p

.control
  * 1. DC Sweep to find the high-gain region (trip point)
  dc Vin 0 1.8 0.01
  meas dc v_trip when v(Out)=0.9

  * 2. AC Analysis
  * Set Vin to the trip point and add AC stimulus
  alter Vin dc = v_trip
  alter Vin ac = 1
  ac dec 100 1 1G

  let gain_db = vdb(Out)
  let phase = 180/PI * cph(v(Out))

  meas ac low_freq_gain find gain_db at=10
  meas ac f_3db when gain_db=(low_freq_gain-3) fall=1
  meas ac unity_gain_freq when gain_db=0 fall=1
  meas ac phase_margin find phase when gain_db=0 fall=1

  * 3. Transient Analysis for Slew Rate
  * Apply a large step input
  alter Vin ac = 0
  alter @Vin[pulse] = [ 0.4 1.4 1n 1n 1n 5u 10u ]
  tran 10n 10u

  meas tran t_rise trig v(Out) val=0.6 rise=1 targ v(Out) val=1.2 rise=1
  meas tran t_fall trig v(Out) val=1.2 fall=1 targ v(Out) val=0.6 fall=1

  * Calculate slew rate in V/us
  let sr_rise = 0.6 / (t_rise * 1e6)
  let sr_fall = 0.6 / (t_fall * 1e6)
  print sr_rise sr_fall

  quit
.endc
.end

